\title{A Carry-Counting Reformulation of Cusick's\\ Sum-of-Digits Inequality, with an Explicit Density Gap}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
Let $s_2(n)$ denote the binary digit sum (Hamming weight) of a nonnegative integer $n$. For a fixed positive integer $t$, Cusick's conjecture concerns the asymptotic density $c_t = \dens\{\, n \ge 0 : s_2(n+t) \ge s_2(n)\,\}$ and asserts the explicit lower bound $c_t \ge \tfrac{1}{2} + 2^{-(2 s_2(t)+1)}$. We isolate and formalize the structural core of the problem: the inequality $s_2(n+t) \ge s_2(n)$ is \emph{exactly equivalent} to the statement that the number of carries produced when adding $n$ and $t$ in base $2$ is at most $s_2(t)$. Defining the carry count via Kummer's theorem as $\carries(t,n) = v_2\binom{n+t}{t}$, we prove the conservation identity $s_2(n+t) + \carries(t,n) = s_2(n) + s_2(t)$ and derive the equivalence $s_2(n) \le s_2(n+t) \iff \carries(t,n) \le s_2(t)$. We supply rigorous density witnesses: a no-carry high-bit lemma, infinitude of the Cusick good set for every $t$, an exact 2-adic characterization of the $t=1$ case, and the exact finite density $c_1 = 3/4$, which strictly exceeds the conjectured bound $5/8$. All results are fully formalized and machine-verified. We discuss how the reformulation reduces the full asymptotic bound to a spectral statement about a finite transfer operator whose size depends only on $s_2(t)$.
\end{abstract}

\section{Introduction}

\subsection{The problem}
The binary digit sum (or \emph{Hamming weight}) $s_2 : \NN \to \NN$ counts the number of $1$'s in the base-$2$ expansion of its argument:
\[
s_2(n) = \sum_{i \ge 0} \varepsilon_i, \qquad n = \sum_{i \ge 0} \varepsilon_i 2^i, \quad \varepsilon_i \in \{0,1\}.
\]
It appears in the Gelfond problems on digit sums, in coding theory as the weight function of the binary cube, and in the analysis of algorithms.

Thomas Cusick raised the following question. Fix $t \ge 1$ and consider, as $n$ ranges over $\NN$, whether $s_2(n+t) \ge s_2(n)$. Define the \emph{Cusick density}
\[
c_t = \lim_{k \to \infty} \frac{\#\{\, n < 2^k : s_2(n+t) \ge s_2(n)\,\}}{2^k}.
\]
A naive symmetry heuristic predicts $c_t \approx 1/2$. Cusick conjectured instead that $c_t > 1/2$ for all $t$, and in sharp quantitative form,
\[
\boxed{\,c_t \ge \tfrac{1}{2} + 2^{-(2 s_2(t)+1)}.\,}
\]

\subsection{Contribution}
This paper formalizes the structural reformulation underlying all known approaches, together with rigorous boundary witnesses. We contribute:
\begin{enumerate}
\item A definition of the carry count $\carries(t,n)$ via Kummer's theorem and a proof of Kummer's identity in subtraction form (Theorem~\ref{thm:kummer}).
\item The carry conservation identity $s_2(n+t) + \carries(t,n) = s_2(n) + s_2(t)$ (Theorem~\ref{thm:conserve}).
\item The Cusick reformulation $s_2(n) \le s_2(n+t) \iff \carries(t,n) \le s_2(t)$ (Theorem~\ref{thm:reform}), with the extremal no-carry case and an unconditional total bound (Theorems~\ref{thm:nocarry},~\ref{thm:total}).
\item Density witnesses: a no-carry high-bit lemma (Theorem~\ref{thm:highbit}), infinitude of the good set for every $t$ (Theorem~\ref{thm:infinite}), the 2-adic $t=1$ characterization (Theorem~\ref{thm:t1iff}), and the exact $t=1$ density $c_1 = 3/4$ (Theorem~\ref{thm:t1dens}).
\end{enumerate}
All statements are machine-verified. We delineate what is proved (the reformulation and the $t=1$ instance) from what remains open (the full asymptotic bound for general $t$).

\subsection{Background: Kummer's and Legendre's theorems}
Legendre's formula gives $v_p(n!) = (n - S_p(n))/(p-1)$, where $S_p$ is the base-$p$ digit sum. Applied to the three factorials in $\binom{n+t}{t}$ it yields $(p-1)\,v_p\binom{n+t}{t} = S_p(n) + S_p(t) - S_p(n+t)$. Kummer's theorem interprets $v_p\binom{n+t}{t}$ as the number of base-$p$ carries in $n+t$. For $p=2$ the prefactor $p-1=1$ vanishes, collapsing both into the statement driving this paper: the number of binary carries in $n+t$ equals $s_2(n)+s_2(t)-s_2(n+t)$. Subadditivity (Fact~\ref{fact:sub}) merely licenses the truncated $\NN$-subtraction.

\section{Definitions and notation}
Throughout, $n,t,L,j,m,k$ denote nonnegative integers and subtraction on $\NN$ is truncated ($a-b = 0$ when $a<b$).

\begin{definition}[Binary digit sum]
$s_2(n)$ is the sum of the base-$2$ digits of $n$; equivalently $s_2(n) = \sum_i \varepsilon_i$ where $n = \sum_i \varepsilon_i 2^i$, $\varepsilon_i \in \{0,1\}$.
\end{definition}

\begin{definition}[2-adic valuation]
For $m \ge 1$, $v_2(m)$ is the largest $e$ with $2^e \mid m$. The arguments arising below are positive.
\end{definition}

\begin{definition}[Carry count, via Kummer]
For $t,n \ge 0$, the \emph{carry count} of the binary addition $n+t$ is
\[
\carries(t,n) = v_2\binom{n+t}{t}.
\]
By Kummer's theorem this equals the number of carries when $n$ and $t$ are added in base $2$.
\end{definition}

\begin{definition}[Good set and density]
$G_t = \{\, n \ge 0 : s_2(n) \le s_2(n+t)\,\}$, and $c_t = \dens(G_t)$ when the limit exists.
\end{definition}

\begin{fact}[Subadditivity / Legendre]\label{fact:sub}
$s_2(n+t) \le s_2(n) + s_2(t)$ for all $n,t$.
\end{fact}

\begin{fact}[Kummer / Legendre digit formula]\label{fact:kummer}
For $p=2$, $(2-1)\,v_2\binom{n+t}{t} = s_2(t) + s_2(n) - s_2(n+t)$, which over $\NN$ (using Fact~\ref{fact:sub}) reads $v_2\binom{n+t}{t} = s_2(t) + s_2(n) - s_2(n+t)$.
\end{fact}

\section{The carry reformulation}

\begin{theorem}[Kummer's identity, subtraction form]\label{thm:kummer}
For all $n,t \ge 0$, $\;\carries(t,n) = s_2(t) + s_2(n) - s_2(n+t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Specialize Fact~\ref{fact:kummer} to $p=2$; the factor $p-1=1$ disappears, and unfolding $\carries(t,n) = v_2\binom{n+t}{t}$ gives the claim.
\end{proof}

\begin{theorem}[Carry conservation identity]\label{thm:conserve}
For all $n,t \ge 0$, $\; s_2(n+t) + \carries(t,n) = s_2(n) + s_2(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:kummer} with Fact~\ref{fact:sub}, which makes the truncated subtraction genuine; rearrange the resulting integer identity (a linear-arithmetic step).
\end{proof}

This identity is a conservation law: each carry destroys exactly one unit of digit sum, and nothing else changes the total.

\begin{theorem}[Cusick reformulation]\label{thm:reform}
For all $n,t \ge 0$,
\[
s_2(n) \le s_2(n+t) \quad\Longleftrightarrow\quad \carries(t,n) \le s_2(t).
\]
\end{theorem}
\begin{proof}[Proof sketch]
From Theorem~\ref{thm:conserve}, $s_2(n+t) - s_2(n) = s_2(t) - \carries(t,n)$ as genuine integers, so $s_2(n+t) \ge s_2(n) \iff s_2(t) \ge \carries(t,n)$.
\end{proof}

\begin{remark}
The one-sided bound $\carries(t,n) \le s_2(t)$ is \emph{not} universal; by Theorem~\ref{thm:reform} it holds exactly on $G_t$. E.g. $n=3,t=1$: $\carries(1,3) = v_2\binom{4}{1} = 2 > 1 = s_2(1)$, matching $s_2(4)=1<2=s_2(3)$.
\end{remark}

\begin{theorem}[No-carry extremal case]\label{thm:nocarry}
If $\carries(t,n) = 0$ then $s_2(n+t) = s_2(n) + s_2(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Set the carry term to $0$ in Theorem~\ref{thm:conserve}.
\end{proof}

\begin{theorem}[Unconditional total bound]\label{thm:total}
For all $n,t$, $\;\carries(t,n) \le s_2(n) + s_2(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from Theorem~\ref{thm:conserve} since $s_2(n+t) \ge 0$.
\end{proof}

\section{Density witnesses}

\begin{theorem}[No-carry high bit]\label{thm:highbit}
If $t < 2^L$ then $\; s_2(t + 2^L) = s_2(t) + 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Since $t < 2^L$, the base-$2$ length of $t$ is at most $L$, so position $L$ is free; adjoining the digit $1$ there adds one new $1$ without any carry. Formally, write the digits of $t+2^L$ as those of $t$, zero-padded to length $L$, followed by a single $1$, and sum.
\end{proof}

\begin{theorem}[Infinitude of the good set]\label{thm:infinite}
For every $t \ge 0$, $G_t$ is infinite, witnessed by $n = 2^{\,j+t}$ for $j \ge 0$.
\end{theorem}
\begin{proof}[Proof sketch]
For $n = 2^{j+t}$ with exponent above all bits of $t$, adding $t$ produces no carry; by Theorem~\ref{thm:highbit} the digit sum is additive, so $s_2(n+t) = s_2(n)+s_2(t) \ge s_2(n)$. These $n$ are distinct.
\end{proof}

\begin{theorem}[The $t=1$ characterization]\label{thm:t1iff}
For all $n \ge 0$, $\; s_2(n) \le s_2(n+1) \iff n \bmod 4 \ne 3$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:reform} with $s_2(1)=1$, the condition is $\carries(1,n) \le 1$. Since $\binom{n+1}{1} = n+1$, $\carries(1,n) = v_2(n+1)$, so the condition is $v_2(n+1) \le 1$, i.e. $4 \nmid (n+1)$, i.e. $n \not\equiv 3 \pmod 4$.
\end{proof}

\begin{theorem}[Exact $t=1$ density]\label{thm:t1dens}
For every $m \ge 0$, exactly $3m$ of the integers $n \in [0,4m)$ satisfy $s_2(n) \le s_2(n+1)$. Hence $c_1 = 3/4 = \tfrac12 + \tfrac14$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:t1iff} the good integers are those with $n \bmod 4 \ne 3$; each block of four contributes exactly three. Induct on $m$; the step is a residue count over one block, valid for all $m$.
\end{proof}

\begin{corollary}[Explicit gap, $t=1$]
Since $s_2(1)=1$, the conjectured bound is $\tfrac12 + 2^{-3} = \tfrac58$. The exact value $c_1 = \tfrac34 = \tfrac68 \ge \tfrac58$ confirms the gap with room to spare.
\end{corollary}

\section{Worked examples}
Each case below is hand-checkable and confirmed numerically.

\noindent\textbf{Ex.\ 6.1} ($t=1,n=5$): $101 \to 110$, one carry. $s_2(5)=2,s_2(1)=1,s_2(6)=2$, so $2+1=2+1$; $1 \le s_2(1)$, inequality holds with equality. $\binom61=6$, $v_2(6)=1$.\\
\textbf{Ex.\ 6.2} ($t=1,n=7$): $111\to1000$, three carries. $s_2(7)=3,s_2(8)=1$, so $\carries=3>1=s_2(1)$: inequality fails ($7\equiv3\bmod4$). $\binom81=8$, $v_2(8)=3$.\\
\textbf{Ex.\ 6.3} ($t=3,n=8$): $1000+011=1011$, no carry. $s_2(11)=3=s_2(8)+s_2(3)$: maximal gain. $\binom{11}{3}=165$, $v_2=0$.\\
\textbf{Ex.\ 6.4} ($t=1$ block): on $\{0,1,2,3\}$ the inequality holds for $0,1,2$ and fails for $3$; three of four, giving $c_1=3/4$.\\
\textbf{Ex.\ 6.5} (empirical): over $[0,2^{22})$, $c_3=0.6875 \ge 0.53125$ and $c_7=0.671875 \ge 0.50781$; all powers of two return exactly $0.75$.

\section{Reduction to a transfer operator}
The reformulation exhibits $c_t = \dens\{n : \carries(t,n) \le s_2(t)\}$ as a statement about the limiting distribution of $v_2\binom{n+t}{t}$. Reading the binary digits of $n$ least-to-most significant, carry propagation for fixed $t$ is a deterministic finite computation whose state records the carry and the local configuration of $t$'s bits; the number of states is controlled by $s_2(t)$. Consequently:
\begin{itemize}
\item \emph{Existence/rationality}: block counts obey a linear recurrence; the Cesàro limit $c_t$ is rational with denominator a power of $2$ times a bounded factor.
\item \emph{The constant}: the surplus $2^{-(2 s_2(t)+1)}$ is a stationary/spectral quantity of a finite matrix of size $O(s_2(t))$, explaining its dependence on $s_2(t)$ alone.
\item \emph{Powers of two}: for $t = 2^j$ the automaton is $j$-independent up to shift, predicting $c_{2^j} = 3/4$.
\end{itemize}

\section{Future directions}
\begin{enumerate}
\item The full explicit bound $c_t \ge \tfrac12 + 2^{-(2 s_2(t)+1)}$, via finite transfer-operator stationary distributions whose size depends only on $s_2(t)$.
\item Existence and rationality of $c_t$ via automaton-driven linear recurrences.
\item Exact density $c_{2^j} = 3/4$ for powers of two, by a shift argument lifting the $t=1$ case using Theorem~\ref{thm:highbit}.
\item A matching upper bound $c_t \le 1 - 2^{-(2 s_2(t)+1)}$ by symmetry of the conservation identity.
\end{enumerate}

\section{Discussion}
The reformulation replaces the erratic function $s_2$ with the locally computable quantity $\carries$: digit sums of $n$ and $n+t$ are individually irregular, but their difference is fixed by the local carry structure, which a finite automaton tracks exactly. The reformulation is an equivalence (nothing is lost), the constant depends on $t$ only through $s_2(t)$ (forced by the automaton's state space), and the $t=1$ case is exact and fully proved (a residue induction, not enumeration), anchoring the explicit gap unconditionally. We do not claim the general asymptotic bound, which awaits the spectral analysis.

\section{Conclusion}
The Cusick inequality $s_2(n+t)\ge s_2(n)$ is exactly the carry condition $\carries(t,n) \le s_2(t)$ with $\carries(t,n) = v_2\binom{n+t}{t}$. The conservation identity $s_2(n+t) + \carries(t,n) = s_2(n) + s_2(t)$ is the linchpin, yielding the extremal no-carry gain, the unconditional total bound, infinitude of the good set, and the exact $t=1$ density $c_1 = 3/4 \ge 5/8$. The reformulation recasts the remaining bound as a finite spectral problem.

